SELECT trm_sn, enct_cycl_nm, trm_nm, trm_expln, eng_abbr_nm, dmn_nm, prm_vl_cn , strg_frm_nm, indct_frm_nm, pbadms_std_cd_nm, jrsd_inst_nm, synm_cn, dscd_yn FROM tb_std_trm WHERE (trm_nm LIKE '%' || #{keyword} || '%' OR eng_abbr_nm LIKE '%' || UPPER(#{keyword}) || '%')
AND dscd_yn = 'N'
ORDER BY CASE WHEN trm_nm = #{keyword} OR eng_abbr_nm = UPPER(#{keyword}) THEN 0 ELSE 1 END , LENGTH(trm_nm), trm_nm LIMIT #{limit}

SELECT word_sn, enct_cycl_nm, word_nm, eng_abbr_nm, eng_nm, word_expln , frm_word_yn, dmn_clsf_nm, synm_cn, phwrd_cn, dscd_yn FROM tb_std_word WHERE (word_nm LIKE '%' || #{keyword} || '%' OR eng_abbr_nm = UPPER(#{keyword}) OR synm_cn LIKE '%' || #{keyword} || '%' OR phwrd_cn LIKE '%' || #{keyword} || '%')
AND dscd_yn = 'N'
ORDER BY CASE WHEN word_nm = #{keyword} THEN 0 ELSE 1 END , LENGTH(word_nm), word_nm LIMIT #{limit}
